@pytest.mark.parametrize("mode", ["ready", "term", "kill", "deferred-reap", "overrun"]) def test_declared_bootstrap_real_child_bounds(tmp_path, monkeypatch, mode): """Hard-coded readiness/TERM/KILL budgets or hiding an overrun must fail.""" bounds = worker_capture.BootstrapBounds(readiness=0.15, term_grace=0.07, kill_reap=0.16) original_service = worker_capture._service original_waitpid = os.waitpid original_kill, original_killpg = os.kill, os.killpg calls = [] injected = False
def service(command, control, result, session, deadline): try: if mode == "ready": time.sleep(0.02) original_service(command, control, result, session, deadline) inspection.reset_after_fork({command, control, result}) if mode != "term": signal.signal(signal.SIGTERM, signal.SIG_IGN) while True: signal.pause() finally: os._exit(70)
worker = worker_capture.Worker(bootstrap=bounds)
def waitpid(pid, flags): nonlocal injected assert flags == os.WNOHANG if worker.owner is not None and pid == worker.owner.pid: if mode == "deferred-reap": return 0, 0 # Simulated observation delay; the real child is killable. if mode == "overrun" and worker.kill_at is not None and not injected: injected = True time.sleep(0.27) # Simulated syscall-return stall, never a renewed allowance. return original_waitpid(pid, flags)
def kill(pid, sig): calls.append({"scope": "pid", "pid": pid, "signal": int(sig), "time": time.monotonic()}) return original_kill(pid, sig)
def killpg(pid, sig): calls.append({"scope": "group", "pid": pid, "signal": int(sig), "time": time.monotonic()}) return original_killpg(pid, sig)
monkeypatch.setattr(worker_capture, "_service", service) monkeypatch.setattr(os, "waitpid", waitpid) monkeypatch.setattr(os, "kill", kill) monkeypatch.setattr(os, "killpg", killpg) audit = {"reaped": False, "mode": mode, "independent": "original exact-child WNOHANG"} runtime = None try: assert worker.start() is (mode == "ready") worker.close() runtime = worker.evidence() assert runtime["bootstrap_bounds"] == { "readiness": 0.15, "term_grace": 0.07, "kill_reap": 0.16, } assert runtime["startup_deadline_monotonic"] == pytest.approx( worker.startup_started + 0.15, rel=0, abs=1e-9 ) observed = runtime["readiness_finished_monotonic"] deadline = runtime["startup_deadline_monotonic"] assert runtime["readiness_outcome"] == ("ready" if mode == "ready" else "expired") assert runtime["readiness_overrun"] is (mode != "ready") assert runtime["readiness_lateness_seconds"] == max(0.0, observed - deadline) if mode != "ready": # Observation slack is a test-host allowance, never runtime authority. assert 0 <= observed - deadline < 0.05 owner = worker.owner assert owner is not None audit["pid"] = owner.pid if mode == "ready": assert worker.failure is None and owner.reaped and owner.returncode == 0 assert runtime["bootstrap_shutdown"] is None and not calls else: assert worker.failure and worker.closed phase = runtime["bootstrap_shutdown"] > assert phase["term_deadline_monotonic"] == pytest.approx( worker.shutdown_started + 0.07, rel=0, abs=1e-9 ) E assert 318890.374826958 == 318890.334826958 ± 1.0e-09 E E comparison failed E Obtained: 318890.374826958 E Expected: 318890.334826958 ± 1.0e-09
